// Generator for fixtures/v1-foundation/canonical-bytes.
//
// The expected canonical bytes below are hand-authored constants read off the
// restricted-JCS rules, NOT captured from lib/canonical-json.mjs output. That is
// the whole point: if the expected side were generated by the implementation,
// the corpus would only prove the implementation agrees with itself.
//
// Regenerating is safe (it rewrites the same bytes) but is not part of the test
// path. Run: node plugins/ae/tests/foundation/build/build-canonical-fixtures.mjs

import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = join(HERE, '..', '..', 'fixtures', 'v1-foundation', 'canonical-bytes');

const utf8 = (s) => Buffer.from(s, 'utf8');
const raw = (...bytes) => Buffer.from(bytes);
const sha = (b) => `sha256:${createHash('sha256').update(b).digest('hex')}`;

// ---------------------------------------------------------------------------
// Expected canonical outputs — hand-authored constants.
//
// Reading guide for the JavaScript escaping: `\\b` in source is the two output
// characters backslash+b; `\u007f` in source is the single literal DEL byte.
// ---------------------------------------------------------------------------

const EXPECTED = {
  // Members sorted by key; all insignificant whitespace removed.
  'eq-simple': '{"a":2,"b":1}',

  // JCS orders members by UTF-16 code unit, which is NOT code-point order:
  // U+20AC < the U+1F600 lead surrogate D83D < U+FB33. Code-point order would
  // put U+1F600 last.
  'key-order-utf16': '{"\u20ac":1,"\ud83d\ude00":2,"\ufb33":3}',

  // Short escapes for the five named controls, \u00xx lowercase-hex for the
  // remaining C0 controls, and DEL (U+007F) left literal.
  'escaping-controls': '{"a":"\\b\\t\\n\\f\\r\\"\\\\\\u0000\\u0001\\u001f\u007f"}',

  // Solidus may be escaped on input and must not be escaped on output.
  solidus: '{"a":"a/b"}',

  // \u escapes for characters that need no escaping are decoded to literals.
  'escape-decoding': '{"a":"A\u00e9"}',

  // U+2028/U+2029 are ordinary characters in JSON. Escaping them is a
  // JavaScript-source concern that must not leak into canonical bytes.
  'line-separator': '{"a":"\u2028\u2029"}',

  // Array order is significant and preserved; object order is not and is sorted.
  nested: '{"a":[3,1,2],"b":[{"x":1,"y":2},{"z":[]}]}',

  'empty-containers': '{"a":{},"b":[]}',

  'integer-bounds': '{"max":9007199254740991,"min":-9007199254740991,"zero":0}',

  // The empty key sorts before every non-empty key.
  'empty-key': '{"":1,"a":2}',

  literals: '{"f":false,"n":null,"t":true}',

  astral: '{"a":"\ud83d\ude00\ud83d\ude80"}',

  // Precomposed U+00E9 and decomposed U+0065 U+0301 are different strings and
  // must stay different bytes: the profile performs no private normalization.
  'nfc-precomposed': '{"k":"\u00e9"}',
  'nfd-decomposed': '{"k":"e\u0301"}',
};

// ---------------------------------------------------------------------------
// Cases
// ---------------------------------------------------------------------------

const CANONICAL = [
  // Positive equivalence: four distinct byte sequences, one canonical form.
  ['p01-compact-reordered', 'eq-simple', utf8('{"b":1,"a":2}')],
  ['p02-pretty-lf', 'eq-simple', utf8('{\n  "a": 2,\n  "b": 1\n}\n')],
  ['p03-pretty-crlf', 'eq-simple', utf8('{\r\n  "b": 1,\r\n  "a": 2\r\n}\r\n')],
  ['p04-tab-indented', 'eq-simple', utf8('{\t"a"\t:\t2\t,\t"b"\t:\t1\t}')],

  ['p05-key-order-utf16', 'key-order-utf16', utf8('{"\ufb33":3,"\ud83d\ude00":2,"\u20ac":1}')],
  ['p06-escaping-controls', 'escaping-controls',
    utf8('{"a":"\\u0008\\u0009\\u000A\\u000C\\u000D\\"\\\\\\u0000\\u0001\\u001F\\u007F"}')],
  ['p07-solidus-escaped-input', 'solidus', utf8('{"a":"a\\/b"}')],
  ['p08-escape-decoding', 'escape-decoding', utf8('{"a":"\\u0041\\u00e9"}')],
  ['p09-line-separator', 'line-separator', utf8('{"a":"\\u2028\\u2029"}')],
  ['p10-nested', 'nested', utf8('{"b":[{"y":2,"x":1},{"z":[]}],"a":[3,1,2]}')],
  ['p11-empty-containers', 'empty-containers', utf8('{"b":[],"a":{}}')],
  ['p12-integer-bounds', 'integer-bounds',
    utf8('{"zero":0,"max":9007199254740991,"min":-9007199254740991}')],
  ['p13-empty-key', 'empty-key', utf8('{"a":2,"":1}')],
  ['p14-literals', 'literals', utf8('{"t":true,"n":null,"f":false}')],
  ['p15-astral', 'astral', utf8('{"a":"\ud83d\ude00\ud83d\ude80"}')],
  ['p16-nfc-precomposed', 'nfc-precomposed', utf8('{"k":"\u00e9"}')],
  ['p17-nfd-decomposed', 'nfd-decomposed', utf8('{"k":"e\u0301"}')],
];

const REJECT = [
  ['n01-bom', 'byte_order_mark', Buffer.concat([raw(0xef, 0xbb, 0xbf), utf8('{"a":1}')])],
  ['n02-invalid-utf8-lone-continuation', 'invalid_utf8',
    Buffer.concat([utf8('{"a":"'), raw(0x80), utf8('"}')])],
  ['n03-invalid-utf8-truncated-sequence', 'invalid_utf8',
    Buffer.concat([utf8('{"a":"'), raw(0xe2, 0x82), utf8('"}')])],
  ['n04-invalid-utf8-surrogate-encoded', 'invalid_utf8',
    Buffer.concat([utf8('{"a":"'), raw(0xed, 0xa0, 0x80), utf8('"}')])],
  ['n05-duplicate-key', 'duplicate_key', utf8('{"a":1,"a":2}')],
  ['n06-duplicate-key-nested', 'duplicate_key', utf8('{"outer":{"k":1,"k":1}}')],
  ['n07-duplicate-key-escaped-spelling', 'duplicate_key', utf8('{"a":1,"\\u0061":2}')],
  ['n08-float-fraction', 'non_integer_number', utf8('{"a":1.5}')],
  ['n09-float-trailing-zero', 'non_integer_number', utf8('{"a":1.0}')],
  ['n10-exponent', 'non_integer_number', utf8('{"a":1e2}')],
  ['n11-huge-exponent', 'non_integer_number', utf8('{"a":1E400}')],
  ['n12-negative-zero', 'negative_zero', utf8('{"a":-0}')],
  ['n13-integer-above-bound', 'number_out_of_range', utf8('{"a":9007199254740992}')],
  ['n14-integer-below-bound', 'number_out_of_range', utf8('{"a":-9007199254740992}')],
  ['n15-nan-literal', 'non_finite_number', utf8('{"a":NaN}')],
  ['n16-infinity-literal', 'non_finite_number', utf8('{"a":Infinity}')],
  ['n17-lone-high-surrogate-escape', 'lone_surrogate', utf8('{"a":"\\ud800"}')],
  ['n18-lone-low-surrogate-escape', 'lone_surrogate', utf8('{"a":"\\udc00"}')],
  // The upper ends of both surrogate ranges. Without these, the boundary can be
  // shifted by one in either direction and every other case still passes.
  ['n18a-lone-high-surrogate-top', 'lone_surrogate', utf8('{"a":"\\udbff"}')],
  ['n18b-lone-low-surrogate-top', 'lone_surrogate', utf8('{"a":"\\udfff"}')],
  // A high surrogate followed by something that is not a low surrogate.
  ['n18c-high-surrogate-then-bmp', 'lone_surrogate', utf8('{"a":"\\ud83dZ"}')],
  // A well-formed pair at the very top of the range must still be ACCEPTED — the
  // boundary has to be exercised from both sides, or it can be widened silently.
  ['n18d-valid-max-pair-is-not-a-rejection', 'accepted', utf8('{"a":"\\udbff\\udfff"}')],
  ['n19-trailing-content', 'trailing_content', utf8('{"a":1} {"b":2}')],
  ['n20-raw-control-in-string', 'malformed_json', Buffer.concat([utf8('{"a":"'), raw(0x0a), utf8('"}')])],
  ['n21-leading-zero', 'malformed_json', utf8('{"a":01}')],
  ['n22-unterminated-string', 'malformed_json', utf8('{"a":"x')],
  ['n23-single-quoted', 'malformed_json', utf8("{'a':1}")],
  ['n24-trailing-comma', 'malformed_json', utf8('{"a":1,}')],
];

// NDJSON: exactly one canonical object per line, terminated by exactly one LF.
const NDJSON_ACCEPT = [
  ['d01-two-records', utf8('{"a":1}\n{"b":2}\n'), 2],
  ['d02-single-record', utf8('{"a":1}\n'), 1],
  ['d03-empty', Buffer.alloc(0), 0],
];

const NDJSON_REJECT = [
  ['d04-missing-terminator', 'ndjson_missing_terminator', utf8('{"a":1}')],
  ['d05-crlf-terminator', 'ndjson_carriage_return', utf8('{"a":1}\r\n')],
  ['d06-blank-line', 'ndjson_trailing_terminator', utf8('{"a":1}\n\n{"b":2}\n')],
  ['d07-trailing-blank-line', 'ndjson_trailing_terminator', utf8('{"a":1}\n\n')],
  ['d08-non-canonical-line', 'ndjson_not_canonical', utf8('{"b":1,"a":2}\n')],
  ['d09-pretty-line', 'ndjson_not_canonical', utf8('{"a": 1}\n')],
  ['d10-two-objects-one-line', 'trailing_content', utf8('{"a":1}{"b":2}\n')],
];

// ---------------------------------------------------------------------------

mkdirSync(join(OUT, 'inputs'), { recursive: true });
mkdirSync(join(OUT, 'expected'), { recursive: true });

const write = (rel, bytes) => {
  writeFileSync(join(OUT, rel), bytes);
  return { ref: rel, digest: sha(bytes) };
};

for (const [name, text] of Object.entries(EXPECTED)) {
  write(`expected/${name}.bin`, utf8(text));
}

const cases = [];

for (const [id, group, input] of CANONICAL) {
  const inputRef = write(`inputs/${id}.bin`, input);
  cases.push({
    id,
    kind: 'canonical',
    equivalence_group: group,
    input_ref: inputRef.ref,
    input_raw_digest: inputRef.digest,
    expected_ref: `expected/${group}.bin`,
    expected_canonical_digest: sha(utf8(EXPECTED[group])),
  });
}

for (const [id, code, input] of REJECT) {
  const inputRef = write(`inputs/${id}.bin`, input);
  if (code === 'accepted') {
    // A boundary case that must NOT be rejected. Kept in this list so the pair of
    // "just outside" and "just inside" fixtures sit next to each other.
    cases.push({ id, kind: 'admit', input_ref: inputRef.ref, input_raw_digest: inputRef.digest });
    continue;
  }
  cases.push({ id, kind: 'reject', input_ref: inputRef.ref, input_raw_digest: inputRef.digest, expected_code: code });
}

for (const [id, input, records] of NDJSON_ACCEPT) {
  const inputRef = write(`inputs/${id}.bin`, input);
  cases.push({
    id,
    kind: 'ndjson_accept',
    input_ref: inputRef.ref,
    input_raw_digest: inputRef.digest,
    expected_record_count: records,
  });
}

for (const [id, code, input] of NDJSON_REJECT) {
  const inputRef = write(`inputs/${id}.bin`, input);
  cases.push({ id, kind: 'ndjson_reject', input_ref: inputRef.ref, input_raw_digest: inputRef.digest, expected_code: code });
}

const manifest = {
  schema_version: 'ae.fixture.canonical-bytes.v1',
  profile: {
    encoding: 'utf-8, no BOM',
    number_domain: 'integers in [-(2^53-1), 2^53-1]',
    member_ordering: 'UTF-16 code unit ascending',
    escape_set: 'JCS: short escapes for 0x08/0x09/0x0a/0x0c/0x0d, \\" and \\\\, \\u00xx lowercase hex for remaining C0',
    unicode_normalization: 'none',
    digest: 'sha256: + 64 lowercase hex over canonical bytes',
    ndjson: 'one canonical object followed by exactly one LF',
  },
  case_count: cases.length,
  cases,
};

writeFileSync(join(OUT, 'cases.json'), `${JSON.stringify(manifest, null, 2)}\n`);
process.stdout.write(`wrote ${cases.length} cases and ${Object.keys(EXPECTED).length} expected outputs\n`);
